ref={"v":f"{B}/ref-viking.png","m":f"{B}/ref-modern.png","vm":f"{B}/ref-viking.png,{B}/ref-modern.png","n":None,"h":f"{B}/ref-hench.png","mh":f"{B}/ref-modern.png,{B}/ref-hench.png","vh":f"{B}/ref-viking.png,{B}/ref-hench.png","r":f"{B}/ref-ripped.png","vr":f"{B}/ref-viking.png,{B}/ref-ripped.png","f":f"{B}/ref-final.png","mf":f"{B}/ref-modern.png,{B}/ref-final.png","vf":f"{B}/ref-viking.png,{B}/ref-final.png"}
only=sys.argv[1:] 
def run(f):
    i,r,p=f
    out=f"{B}/f{i}.png"
    if os.path.exists(out) and not only: return i,"skip"
    cmd=["python3","scripts/run_image.py",STY+p,"--aspect","9:16","--out",out]
    if ref[r]: cmd+=["--ref",ref[r]]
    for attempt in range(2):
        res=subprocess.run(cmd,capture_output=True,text=True)
        if os.path.exists(out): return i,"ok"
    return i,"FAIL "+(res.stderr or res.stdout)[-200:]
todo=[f for f in F if not only or f[0] in only]
with ThreadPoolExecutor(6) as ex:
    for i,s in ex.map(run,todo): print(i,s,flush=True)
